def _is_prime(num: int) -> bool:
    if num < 2:
        return False
    if num % 2 == 0:
        return num == 2
    i = 3
    while i * i <= num:
        if num % i == 0:
            return False
        i += 2
    return True


def count_up_to(n: int) -> list:
    return [i for i in range(2, n) if _is_prime(i)]
